import sys; sys.path.insert(0, __import__("os").path.join(__import__("os").path.dirname(__file__), "..", "..", "pipeline"))
from scriptkit import sc, ch, save, S

# Grandma Ruth 111 · ANGLE: grandchild rejects handmade gift; years later comes back (hidden message in the hem)

sc("""Sweetheart, in December of two thousand fifteen, I spent four months knitting a sweater for my grandson Tyler. Navy blue, with a white stripe, his school colors. He was fifteen. And on Christmas morning, he held it up, and he laughed, and he said, Grandma, nobody wears stuff like this. His cousins laughed too. He left it on my couch when they went home. And he never knew what I'd stitched inside the hem.""",
   "teenage boy holding up knitted sweater laughing", "NOBODY WEARS THIS")
sc("""Tonight I'm going to tell you where that sweater spent the next nine years, and the night Tyler showed up at my door at twenty-four, with nowhere else to go. And what he found when he finally put it on. Stay with me, honey, because he's sitting in my kitchen right now, and he's knitting.""",
   "young man at kitchen table with knitting needles", "HE'S KNITTING")

ch("Four months")
sc("""I learned to knit from my Grandma Pearl when I was six, honey. And every Christmas, for as long as I've had grandchildren, I've knitted something for each one. Mittens when they're little, scarves when they're bigger. But the year each grandchild turned fifteen, I made them a sweater. A real one. It takes me about four months, now that my fingers are stiff. I start in August.""",
   "elderly woman knitting in armchair by window", "I START IN AUGUST")
sc("""Tyler is Susan's oldest boy, sweetheart. He was such a sweet little thing. When he was five, he used to sit on the floor at my feet while I knitted, and wind the yarn into balls for me. He called it helping. He'd say, Grandma, when I'm big, will you make me a sweater? And I promised him. Every year, he asked. Is it this year, Grandma? Am I big enough?""",
   "small boy winding yarn at grandmother's feet", "AM I BIG ENOUGH?")
sc("""But fifteen is a hard age, honey. By fifteen, Tyler had a phone, and friends I'd never met, and he didn't sit at my feet anymore. He mostly grunted at me. That's normal. I raised a teenage boy myself. But I still remembered that little voice asking, is it this year? So I picked navy and white, his high school colors, the softest wool I could afford. Sixty-two dollars of yarn. In a minute I'll tell you what I hid inside it.""",
   "skeins of navy and white yarn in basket", "SIXTY-TWO DOLLARS OF YARN")

sc("""I knitted it in the evenings, honey, in Harold's old chair, with the television turned down low. Every row, I thought about Tyler. When I did the ribbing on the cuffs, I thought about the time he caught his first fish at Clear Fork Lake and screamed so loud he scared it off the hook. When I did the white stripe, I thought about his first day of kindergarten. A sweater holds every thought you knit into it. I'll tell you about the most important one in a minute.""",
   "close up of hands knitting navy sweater", "EVERY ROW, A THOUGHT")
ch("The hem")
sc("""On the last night, before I sewed up the bottom of the sweater, I did something my Grandma Pearl taught me. She said, Ruthie, always leave a message inside. And I took a little piece of white cotton tape, and with a needle and red thread, I stitched seven words on it. Then I folded it inside the hem, right at the front, where his heart would be, and I sewed it shut. Nobody could see it.""",
   "red thread stitching words on cloth tape", "ALWAYS LEAVE A MESSAGE")
sc("""If Grandma's story is touching your heart, tap the like button for me, sweetheart. It helps more people find these stories. I wrapped that sweater in red paper with a gold bow and put it under the tree with a tag that said, finally, you're big enough. Love, Grandma. I was so proud of that sweater. I'd only done it twice before, for his two older cousins. This was the one he'd asked for since he was five.""",
   "red wrapped present with gold bow under tree", "FINALLY BIG ENOUGH")

ch("Christmas morning")
sc("""And Christmas morning, he opened it last, in front of the whole family, all the cousins in a circle on my living room floor. He held it up. And for one second, honey, I saw it on his face, that little boy. And then one of his cousins snickered. And Tyler looked at the cousins, and back at the sweater, and he laughed. He said, Grandma, nobody wears stuff like this. It's like, from nineteen fifty.""",
   "family on living room floor opening presents", "LIKE FROM 1950")
sc("""Everybody laughed, sweetheart. Even Susan, a little, before she caught herself. I laughed too, because what else do you do? I said, well, you'll grow into it. And I went into the kitchen to check on the ham, and I stood by the sink with the water running, so nobody could hear me. Only my granddaughter Lily noticed. She was eight. She came in and held my hand and didn't say anything.""",
   "elderly woman at kitchen sink hiding tears", "THE WATER RUNNING")
sc("""When they all went home that night, the sweater was still on my couch, folded, with the tag. He'd left it. Maybe by accident. Maybe not. I never asked. I wrapped it in tissue paper and put it in the cedar chest at the foot of my bed, with Harold's Army jacket and my mother's wedding veil. And I closed the lid. And that was where it stayed, honey, for nine years.""",
   "cedar chest at foot of bed with lid open", "THE CEDAR CHEST")

sc("""Some years, sweetheart, I'd open that cedar chest to get something else out, and I'd see the navy wool through the tissue paper. And I'd think about giving it away, to the church clothing drive, to some boy who'd actually wear it. I almost did, twice. But something always stopped me. Grandma Pearl used to say, a gift you make for one person belongs to that person. It waits for them. So I let it wait.""",
   "elderly woman looking into cedar chest", "IT WAITS FOR THEM")
ch("Nine years")
sc("""So far, four months of knitting, seven secret words, a laugh on Christmas morning, and a sweater in a cedar chest. Tyler grew up, sweetheart. He went to college in Columbus. He got a job selling software, made good money, married a girl named Brianna, bought a house with a big lawn. He sent me a card every Christmas, typed, with a photo of the two of them on a beach somewhere. He never mentioned the sweater. And neither did I.""",
   "young couple on beach Christmas card photo", "A TYPED CARD")
sc("""And then, two thousand twenty-four, it all fell apart at once. The company let him go in the spring. Brianna left in the summer. They sold the house to split the money. And by November, my grandson was living in his car, honey. He didn't tell anybody. Not his mother. Not me. He was too ashamed. He'd always been the one who had it together. Stay with me, because then my doorbell rang.""",
   "young man sleeping in car in parking lot", "LIVING IN HIS CAR")

sc("""I found out later that he'd parked outside my house three nights in a row before he rang the bell, honey. He'd sit there in the dark with the engine off, looking at my porch light. He told me, I kept thinking about Christmas, and how I laughed at you. I didn't think I had the right to ask you for anything. I've thought about that a lot since. How a little laugh at fifteen can keep a grown man out in the cold.""",
   "car parked in dark street facing porch light", "THREE NIGHTS IN A ROW")
ch("The doorbell")
sc("""It was the first real snow of the year, sweetheart, eleven o'clock at night, the week before Thanksgiving. I opened the door in my bathrobe, and there was Tyler, twenty-four years old, with a duffel bag and no coat, shaking. He said, Grandma, I'm sorry, I didn't know where else to go. And I said, the only thing I'm sorry about is that you waited this long. Get in here.""",
   "young man with duffel bag at door in snow", "GET IN HERE")
sc("""I made him a grilled cheese and a bowl of tomato soup, at eleven at night, and he ate it like he hadn't eaten in days. Maybe he hadn't. And he told me everything, at my kitchen table. The job, Brianna, the car. He cried, honey. A grown man. I hadn't seen him cry since he fell off his bike at seven. I made up the spare room, the one with the cedar chest.""",
   "grilled cheese and tomato soup late night", "THE SPARE ROOM")

ch("The sweater")
sc("""The house was cold that night, because I keep the heat low to save money. And in the morning, Tyler came down to breakfast wearing the navy blue sweater. He'd been freezing, and he'd opened the cedar chest looking for a blanket. And there it was, in the tissue paper, with the tag still on it. Finally, you're big enough. He stood in my kitchen doorway, wearing it, and he couldn't speak.""",
   "young man in navy knitted sweater kitchen doorway", "STILL WITH THE TAG")
sc("""It fit him perfectly, honey. He'd grown into it, just like I said. He sat down at the table and said, Grandma, I was such a jerk. I'm so sorry. And I said, you were fifteen. Fifteen-year-olds are supposed to be jerks. It's in the Bible somewhere. And he laughed, the first time I'd heard him laugh in years. And then he put his hand on his chest and said, wait. What's this?""",
   "hand pressing on sweater hem feeling something", "WHAT'S THIS?")
sc("""He'd felt the little tape inside the hem, right over his heart. I handed him my sewing scissors. He snipped three stitches, very carefully, and pulled out that little strip of cotton tape. And he read the seven words, in red thread, out loud. Whatever happens, you can always come home. He read it twice. Then he put his head down on my kitchen table, honey, and he sobbed.""",
   "small cloth tape with red stitched words", "YOU CAN ALWAYS COME HOME")

ch("What he said")
sc("""He said, Grandma, you wrote this nine years ago. You didn't know. And I said, honey, I didn't need to know. Grandmas always know somebody's going to need it someday. I've stitched those same seven words inside every sweater I've ever made. Every grandchild of mine who's turned fifteen has that tape in their hem. Most of them have never found it. Tyler's the first one who needed to.""",
   "elderly woman comforting grandson at table", "INSIDE EVERY SWEATER")
sc("""Tyler stayed with me for seven months, sweetheart. He found a job at a hardware store, and then a better one. He fixed everything in my house that Harold used to fix. And one night in January, he picked up my knitting needles from the basket and said, Grandma, teach me. His big hands were so clumsy. His first scarf had more holes than a fishing net. He wore it anyway. Every day.""",
   "young man learning to knit with grandmother", "TEACH ME")

sc("""That Christmas, Tyler wore the navy sweater to dinner, honey. Susan saw it, and she put her hand over her mouth. The cousins were all grown up by then, and one of them, the one who'd snickered, said, hey, I remember that sweater. And Tyler said, yeah. Grandma made it for me. Best thing I own. And he looked right at me across the table. Nobody laughed this time.""",
   "family Christmas dinner young man in navy sweater", "BEST THING I OWN")
ch("Today")
sc("""He has his own apartment now, honey, and a good job, and a sweet girlfriend who teaches second grade. And last month, he finished his first sweater. A tiny one, for his girlfriend's sister's new baby. And before he sewed up the hem, he called me on the phone and asked me how to stitch letters with red thread. I didn't have to ask what he was going to write.""",
   "tiny knitted baby sweater with red thread", "HIS FIRST SWEATER")

ch("Grandma's lesson")
sc("""Here's what I want you to remember, honey. Keep the gift your grandmother made you, even if you laugh at it. Someday you'll understand what's stitched inside. Tell me in the comments, sweetheart, what's the handmade gift you wish you'd kept? There are more of my family's stories in the playlist right there on your screen. Good night. Merry Christmas.""",
   "folded navy knitted sweater by Christmas tree", "KEEP THE GIFT")

for s in S:
    s["cuts"], s["moves"] = 4, True

save("grandma111", "My Grandson LAUGHED at the Sweater I Knitted Him. 9 Years Later...",
     ["Grandma Ruth is a fictional narrator, and this is a fictional story. All names are invented."],
     "grandchild comes back story", minutes=(12, 14.5), voice="en_US-lessac-high")
